import{_ as s,o as e,c as i,a2 as r}from"./chunks/framework.doxMM-x8.js";const c=JSON.parse('{"title":"停服备份并恢复到新目录","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/guides/server-operations","contentType":"guide","prev":{"text":"Node 运行追溯与生命周期","link":"/guides/server-traceability"},"next":{"text":"Web 与同源托管","link":"/guides/server-web"}},"headers":[],"relativePath":"guides/server-operations.md","filePath":"guides/server-operations.md"}'),t={name:"guides/server-operations.md"};function n(p,a,d,h,l,o){return e(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="停服备份并恢复到新目录" tabindex="-1">停服备份并恢复到新目录 <a class="header-anchor" href="#停服备份并恢复到新目录" aria-label="Permalink to &quot;停服备份并恢复到新目录&quot;">​</a></h1><p>目标：备份当前 Node 数据，再恢复到独立的新目录。先完成<a href="./server-traceability">Node 运行追溯</a>，准备已发布资产和已确认的业务记录。需要仓库指定的 Node 24 与 pnpm。以下 Bash 命令从仓库根目录运行；它们写入指定归档和恢复目录。</p><h2 id="创建离线归档" tabindex="-1">创建离线归档 <a class="header-anchor" href="#创建离线归档" aria-label="Permalink to &quot;创建离线归档&quot;">​</a></h2><p>停止使用源目录的服务。在运行 <code>pnpm dev</code> 的终端按 Ctrl+C，等进程退出。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/archives/lab-backup</span></span></code></pre></div><p>成功输出 <code>status: backed-up</code>。归档是一个目录，包含 <code>manifest.json</code>、数据库快照和已验证对象字节。命令独占源目录，逐页读取 ready 文件引用，再流式核对大小和 SHA256。数据库事务不等待文件读取。活动服务仍持有源目录时，备份失败。</p><p>输出可用新目录或现有空目录。安全的 <code>dataDir/backups</code> 可用；输出和临时归档不能落入被复制的 <code>pgdata</code> 树。路径别名按真实目录检查，避免快照递归复制自身。发布只移除确认为空的输出目录，不递归删除已有内容。</p><p>归档正向包含数据库和 ready 对象。它不包含原始 <code>secrets/file-signing-key</code>、上传暂存、日志或环境文件。数据库里的密码、会话和 API key 哈希仍是身份数据，不会被删除。</p><h2 id="恢复并读回" tabindex="-1">恢复并读回 <a class="header-anchor" href="#恢复并读回" aria-label="Permalink to &quot;恢复并读回&quot;">​</a></h2><p>选择不存在或为空的目录；不要选原来的服务目录。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.scratch/restored-lab</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --archive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/archives/lab-backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>成功输出 <code>status: restored</code>。恢复逐级拒绝归档中的链接目录，先核对格式、路径和每个文件，再核对实际复制到 staging 的大小与 SHA256。随后在所属 staging 检查实际数据库历史和 ready 引用。完成校验后预留目标的规范路径锁，不提前创建目标，再通过一次目录重命名发布。发布失败时，新目标保持不存在，原空目录会恢复。非空目标、错误内容和不支持的历史会失败；修正输入或选择新目录后重试。</p><p>Linux 的 SIGTERM/SIGINT 会取消归档操作，等待正在进行的复制结束，再关闭数据库并释放目录所有权。进程异常退出可能在临时目录旁留下 <code>.lab-word-backup-*.json</code> 或 <code>.lab-word-restore-*.json</code> 所有权记录。确认旧进程停止后，用相同命令和目标重试。命令同时取得目标与 staging 的排他权，只核对有效且匹配的记录，并验证目录创建身份；若发布中断，先恢复原空目标，再清理所属 staging。活跃 staging 使用者会阻止回收。创建身份缺失或变化时拒绝清理并保留目录。未知目录、无效记录与其他目标的记录保持原样。Windows 进程终止走这一异常退出恢复路径。已经成功发布的目录保留，仍按非空目标拒绝覆盖。</p><p>登录原账户，打开原 Lab 并下载资产。身份和文件字节保持相同。用原键与原参数重试已成功 Command，得到原结果。旧运行在启动时显示 interrupted；不会自动重放命令或恢复长任务。新签名器生成新的字节 URL。</p><p>当前构建在 <code>0000_baseline</code> 后追加 <code>0001_guide_progress</code>，使用 schema 版本 2。启动与迁移在执行 SQL 前，核对已有历史是否为已知迁移序列的前缀。</p><p>恢复支持基线 schema 1 和当前 schema 2 的归档。实际迁移的哈希与时间戳必须完整匹配已知序列的前缀。恢复先按原始 manifest 核对 staging 的数据库历史、引擎信息、ready 引用和文件字节。校验通过后，才在所属 staging 追加缺失迁移，并发布 schema 版本 2。原归档保持不变。</p><p>基线之前的 Node 历史与 Rust/PostgreSQL 数据仍不受支持。命令拒绝这些归档，不转换或删除这些数据目录。保留目录与归档，使用原源码版本读取；当前构建请选择新的数据目录。</p><h2 id="迁移与密码恢复" tabindex="-1">迁移与密码恢复 <a class="header-anchor" href="#迁移与密码恢复" aria-label="Permalink to &quot;迁移与密码恢复&quot;">​</a></h2><p>统一入口也提供 serve、migrate 和 reset-password。<code>pnpm server</code> 默认启动服务。停服后运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recovery_password</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$recovery_password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset-password</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> member@example.test</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recovery_password</span></span></code></pre></div><p>迁移输出实际验证的 schema 版本，不启动设备或清理循环。密码操作通过标准输入读取新密码，不把密码写入输出。它保留用户身份，撤销旧会话并记录 system 审计。重新启动服务后，用新密码登录。原 <code>pnpm reset-password --email ...</code> 入口仍可用。</p><p>源码归属：<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/server/src/cli.ts" target="_blank" rel="noreferrer">统一 CLI</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/server/src/operations.ts" target="_blank" rel="noreferrer">归档组合</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/server/src/archive-workspace.ts" target="_blank" rel="noreferrer">staging 所有权与恢复</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/server/src/password-operation.ts" target="_blank" rel="noreferrer">共享密码操作</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/server/src/platform/db/index.ts" target="_blank" rel="noreferrer">数据库历史与打开能力</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/server/src/platform/db/snapshot.ts" target="_blank" rel="noreferrer">关闭后的数据库快照</a>和<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/server/src/core/files/archive.ts" target="_blank" rel="noreferrer">Files ready 引用</a>。</p><h2 id="启动与关闭的资源归属" tabindex="-1">启动与关闭的资源归属 <a class="header-anchor" href="#启动与关闭的资源归属" aria-label="Permalink to &quot;启动与关闭的资源归属&quot;">​</a></h2><p>服务先取得目录锁并迁移，完成设备中断恢复，再启动各自的调度器、设备循环、订阅和 HTTP。每个 owner 取得资源时立即登记关闭动作；后续准备失败也会调用这些动作。</p><p>关闭先停止 HTTP 接入，同时结束订阅、停止服务定时器与设备接入。全部已登记 owner 都尝试关闭；一个错误不会跳过其他 owner。服务等待已接入 HTTP 校验、设备报告和数据库操作，再关闭数据库并释放目录锁。原始启动或关闭错误保留在结果与日志中，失败退出不描述为成功。</p><p>组合入口见 <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/apps/server/src/runtime.ts" target="_blank" rel="noreferrer">runtime</a>。原 prepared.stop 回调继续受支持；新增 owner 使用 RuntimeControl.ownStop 在取得资源时登记。</p><hr><p>源码版本：<code>d21b97585cfd</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/guides/server-operations.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,28)])])}const b=s(t,[["render",n]]);export{c as __pageData,b as default};
